import type { SpriteDef } from '../sprite.ts';

/**
 * The grey open space of «Цельность»: the hub office and, darkened by the lighting pass, biome 1
 * (its windowless other side). One kit for every location of the biome: cubicles, copy room,
 * storage, break room, corridor and the archive.
 *
 * Scale: the hero is 86 px tall; floor line (feet) at y = 172, ceiling ~150 px above it.
 * - Structure tiles repeat horizontally, anchor top-left: os_ceiling at y = 0 (rows 21-23 are the
 *   wall-angle trim), os_wall / os_wall_b / os_wall_c at y = floor - 150, os_floor at y = floor.
 *   os_ceiling_light (anchor top-centre) goes at y = 6, two ceiling tiles wide.
 * - Floor props: anchor bottom-centre on the floor line. Seats are 30 px above the floor
 *   (the lit seat face), desk and table tops 40 px.
 * - Wall props (posters, clock, board, exit sign, lamp, switch): anchor centre.
 *   os_extinguisher and os_firehose hang on the wall but keep a bottom-centre anchor.
 * - os_bulb hangs from the ceiling: anchor top-centre.
 * Colours are local (lit) values; emissive bits: CRT text, the troffers, the exit sign, the red
 * lamp, the vending window, the copier scan light, the phone and coffee-maker lamps, the bulb.
 * No lettering anywhere: plates, labels and the poster slogan band are blank for the game's text.
 */

